# Python example:
from rw_sdk import RetryLedger, idempotent
ledger = RetryLedger(persistence='memory')

@idempotent(ledger, operation='chat.create', ttl_seconds=3600)
def create_chat(req):
    # SDK attaches X-RW-Idempotency-Key header automatically
    return client.chat.create(req)

